<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { IconAlertTriangle, IconArrowRight, IconBook2, IconRefresh, IconSettings, IconTimeline } from '@tabler/icons-vue'
import { ApiError } from '../api/client'
import { fetchConfig, saveConfig } from '../api/config'
import {
  cancelExpedition, getExpeditions, getGameplayCodex, getGameplayGrowth, reconcileExpedition,
  type CodexCatalogRule, type GameplayCodex, type GameplayGrowth, type GrowthRuleRole, type GrowthRuleStance, type PersonalityRule,
} from '../api/ecosystem'
import PageHeader from '../components/ui/PageHeader.vue'
import UiDrawer from '../components/ui/UiDrawer.vue'
import UiModal from '../components/ui/UiModal.vue'
import UiState from '../components/ui/UiState.vue'
import UiPagination from '../components/ui/UiPagination.vue'
import { useToast } from '../composables/useToast'
import { useUnsavedChanges } from '../composables/useUnsavedChanges'

type Tab='expeditions'|'growth'|'codex'|'rewards'|'exceptions'
type RuleDomain='roles'|'stances'|'personalities'|'codex'
type LiveEvent={key:string;name:string;region:string;starts_at:string;ends_at:string;active:boolean}
type Reward={event_key:string;milestone:number;reward_type?:string;reward_key?:string;reward_name?:string;quantity:number;description:string}

const route=useRoute(),router=useRouter(),toast=useToast()
const tab=ref<Tab>((route.query.tab as Tab)||'expeditions')
const loading=ref(false),error=ref(''),saving=ref(false)
const items=ref<Record<string,unknown>[]>([]),total=ref(0)
const page=ref(Math.max(1,Number(route.query.page)||1)),limit=ref(20)
const expeditionSummary=reactive({running:0,today_completed:0,overdue:0,cancelled:0})
const filters=reactive({status:String(route.query.status??''),tier:String(route.query.tier??''),account_id:String(route.query.account_id??''),platform:String(route.query.platform??''),from:String(route.query.from??''),to:String(route.query.to??'')})
const growth=ref<GameplayGrowth|null>(null),codex=ref<GameplayCodex|null>(null)
const ruleDomain=ref<RuleDomain>('roles'),ruleIndex=ref(-1),ruleSnapshot=ref('')
const rules=reactive<{roles:GrowthRuleRole[];stances:GrowthRuleStance[];personalities:PersonalityRule[];codex:CodexCatalogRule[]}>({roles:[],stances:[],personalities:[],codex:[]})
const dirty=computed(()=>growth.value!==null&&JSON.stringify(rules)!==ruleSnapshot.value)
useUnsavedChanges(dirty)
const events=ref<LiveEvent[]>([]),rewards=ref<Reward[]>([])
const operation=reactive({type:'',id:'',reason:''}),busy=ref(false)
const confirmation=reactive<{open:boolean;title:string;description:string;action:null|(()=>void|Promise<void>)}>({open:false,title:'',description:'',action:null})

const selectedRule=computed<any>(()=>ruleIndex.value<0?null:rules[ruleDomain.value][ruleIndex.value])
const groupedRewards=computed(()=>events.value.map(event=>({event,rewards:rewards.value.filter(row=>row.event_key===event.key).sort((a,b)=>a.milestone-b.milestone)})).concat(rewards.value.filter(row=>!events.value.some(event=>event.key===row.event_key)).reduce((groups:any[],row)=>{let group=groups.find(item=>item.event.key===row.event_key);if(!group){group={event:{key:row.event_key,name:'未关联活动',region:'-',starts_at:'',ends_at:'',active:false},rewards:[]};groups.push(group)}group.rewards.push(row);return groups},[])))
const rewardWarnings=computed(()=>{const warnings:string[]=[];const seen=new Set<string>();for(const row of rewards.value){const key=`${row.event_key}:${row.milestone}:${row.reward_type||'item'}:${row.reward_key||''}`;if(seen.has(key))warnings.push(`重复奖励 ${key}`);seen.add(key);if(row.quantity<=0)warnings.push(`${key} 的奖励数量无效`);if(!events.value.some(event=>event.key===row.event_key))warnings.push(`${key} 未关联有效活动`)}return warnings})

function askConfirmation(title:string,description:string,action:()=>void|Promise<void>){Object.assign(confirmation,{open:true,title,description,action})}
async function confirmRequestedAction(){const action=confirmation.action;confirmation.open=false;confirmation.action=null;if(action)await action()}
function queryForFilters(){const query:Record<string,string>={tab:tab.value,page:String(page.value)};Object.entries(filters).forEach(([key,value])=>{if(value)query[key]=value});return query}
async function setTab(value:Tab){if(dirty.value){askConfirmation('放弃未保存的成长规则？','切换后当前修改将会丢失。',()=>switchTab(value));return}await switchTab(value)}
async function switchTab(value:Tab){tab.value=value;page.value=1;await router.replace({query:{tab:value,page:'1'}});await load()}
async function applyFilters(){page.value=1;await router.replace({query:queryForFilters()});await load()}
async function changePage(value:number){page.value=value;await router.replace({query:{...route.query,page:String(value)}});await load()}
async function changeLimit(value:number){limit.value=value;await changePage(1)}
async function load(){loading.value=true;error.value='';try{
  if(tab.value==='expeditions'||tab.value==='exceptions'){const params=new URLSearchParams({page:String(page.value),limit:String(limit.value)});if(tab.value==='exceptions')params.set('status','overdue');else Object.entries(filters).forEach(([key,value])=>{if(value)params.set(key,value)});const result=await getExpeditions(params);items.value=result.items;total.value=result.total;Object.assign(expeditionSummary,result.summary)}
  else if(tab.value==='growth'){const result=await getGameplayGrowth();growth.value=result;Object.assign(rules,JSON.parse(JSON.stringify(result.rules)));ruleSnapshot.value=JSON.stringify(rules)}
  else if(tab.value==='codex'){codex.value=await getGameplayCodex(new URLSearchParams({query:String(route.query.query??''),category:String(route.query.category??''),region:String(route.query.region??''),status:String(route.query.codex_status??'')}))}
  else {const [eventRows,rewardRows]=await Promise.all([fetchConfig('live_events'),fetchConfig('reward_tracks')]);events.value=eventRows as LiveEvent[];rewards.value=rewardRows as Reward[]}
}catch(reason){error.value=reason instanceof ApiError?reason.message:'玩法数据加载失败'}finally{loading.value=false}}

function openRule(domain:RuleDomain,index:number){ruleDomain.value=domain;ruleIndex.value=index}
function addRule(domain:RuleDomain){ruleDomain.value=domain;const next:any=domain==='roles'?{name:'',description:'',skill_1:'',skill_2:'',skill_3:'',enabled:true,sort_order:(rules.roles.length+1)*10}:domain==='stances'?{name:'',description:'',enabled:true,sort_order:(rules.stances.length+1)*10}:domain==='personalities'?{name:'',dimension:'care',min_threshold:3,description:'',enabled:true,sort_order:(rules.personalities.length+1)*10}:{category:'',entry_key:'',region:'',source_type:'zone',source_key:'',description:'',enabled:true,sort_order:(rules.codex.length+1)*10};(rules[domain] as any[]).push(next);ruleIndex.value=rules[domain].length-1}
function removeRule(){if(ruleIndex.value<0)return;askConfirmation('删除这条成长规则？','规则会先从编辑列表移除，保存成长规则后正式生效。',()=>{(rules[ruleDomain.value] as any[]).splice(ruleIndex.value,1);ruleIndex.value=-1})}
async function saveRules(){saving.value=true;try{await Promise.all([saveConfig('growth_roles',rules.roles),saveConfig('growth_stances',rules.stances),saveConfig('personality_rules',rules.personalities),saveConfig('codex_catalog',rules.codex)]);ruleSnapshot.value=JSON.stringify(rules);toast.success('成长规则已保存，聊天玩法将读取新配置')}catch(reason){toast.error(reason instanceof Error?reason.message:'规则保存失败')}finally{saving.value=false}}
async function execute(){if(!operation.reason.trim())return toast.error('请填写操作原因');busy.value=true;try{if(operation.type==='cancel')await cancelExpedition(operation.id,operation.reason);else await reconcileExpedition(operation.id,operation.reason);toast.success('远征已处理并写入审计');operation.type='';await load()}catch(reason){toast.error(reason instanceof Error?reason.message:'处理失败')}finally{busy.value=false}}
function openOperation(type:string,id:unknown){operation.type=type;operation.id=String(id);operation.reason=''}
function percent(value:number){return `${Number(value||0).toFixed(1)}%`}
function dateText(value:unknown){if(!value)return '-';const date=new Date(String(value));return Number.isNaN(date.getTime())?String(value):date.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function statusLabel(value:unknown){return ({running:'进行中',claimed:'已结算',cancelled:'已取消'} as Record<string,string>)[String(value)]||String(value||'未知')}
watch(()=>route.query.tab,value=>{if(value&&value!==tab.value){tab.value=value as Tab;load()}})
onMounted(load)
</script>

<template><section class="gameplay-page">
  <PageHeader eyebrow="Gameplay" title="玩法运营" description="监控远征状态、分析成长生态，并直接维护驱动聊天玩法的成长规则。"><template #actions><button class="btn btn-ghost" :disabled="loading" @click="load"><IconRefresh :size="17"/>刷新</button><button v-if="tab==='growth'" class="btn btn-primary" :disabled="saving||!dirty" @click="saveRules">{{saving?'保存中…':'保存成长规则'}}</button></template></PageHeader>
  <nav class="page-tabs" aria-label="玩法运营分区"><button v-for="item in ([['expeditions','远征监控'],['growth','成长运营'],['codex','图鉴进度'],['rewards','奖励轨道'],['exceptions','异常处理']] as [Tab,string][] )" :key="item[0]" :class="{active:tab===item[0]}" @click="setTab(item[0])">{{item[1]}}</button></nav>
  <UiState v-if="error" tone="error" title="玩法数据加载失败" :description="error" action-label="重新加载" @action="load"/>
  <UiState v-else-if="loading" tone="loading" title="正在整理玩法数据" description="统计、规则和运行状态正在同步。"/>

  <template v-else-if="tab==='expeditions'||tab==='exceptions'">
    <div class="metric-strip"><article><span>进行中</span><strong>{{expeditionSummary.running}}</strong></article><article><span>今日完成</span><strong>{{expeditionSummary.today_completed}}</strong></article><article :class="{warning:expeditionSummary.overdue>0}"><span>到期未结算</span><strong>{{expeditionSummary.overdue}}</strong></article><article><span>已取消</span><strong>{{expeditionSummary.cancelled}}</strong></article></div>
    <div v-if="tab==='expeditions'" class="filter-bar"><label>状态<select v-model="filters.status"><option value="">全部状态</option><option value="running">进行中</option><option value="claimed">已结算</option><option value="cancelled">已取消</option><option value="overdue">到期未结算</option></select></label><label>档位<select v-model="filters.tier"><option value="">全部档位</option><option value="1">短途</option><option value="2">常规</option><option value="3">深度</option></select></label><label>平台<select v-model="filters.platform"><option value="">全部平台</option><option value="onebot">OneBot</option><option value="qq_group">官方群</option><option value="qq_guild">官方频道</option></select></label><label class="grow">内部账号<input v-model="filters.account_id" placeholder="输入完整账号 UUID"/></label><button class="btn btn-primary" @click="applyFilters">应用筛选</button></div>
    <UiState v-if="items.length===0" title="等待玩家开始首个远征" :description="tab==='exceptions'?'当前没有到期未结算的异常远征。':'远征玩法已启用；玩家开始远征后，状态、奖励快照和处理入口会出现在这里。'"/>
    <div v-else class="data-panel"><div class="data-panel-head"><strong>{{total}} 条远征记录</strong><span>奖励以出发时快照为准，重复结算受幂等保护</span></div><div class="desktop-table"><table><thead><tr><th>远征</th><th>玩家标识</th><th>档位 / 姿态</th><th>状态</th><th>结束时间</th><th>奖励快照</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="String(row.ID)"><td><strong>{{row.Name||'未命名远征'}}</strong><small>{{row.ID}}</small></td><td><code>…{{String(row.AccountID||'').slice(-8)||'-'}}</code></td><td>{{row.Tier||'-'}} / {{row.Stance||'未设置'}}</td><td><span class="badge" :class="{'badge-warning':row.Status==='running','badge-success':row.Status==='claimed'}">{{statusLabel(row.Status)}}</span></td><td>{{dateText(row.EndsAt)}}</td><td>{{row.RewardItem||'无物品'}} × {{row.RewardQuantity||0}}<small>调查记录 {{row.RewardRecords||0}}</small></td><td><div v-if="row.Status==='running'" class="actions"><button class="btn btn-ghost btn-small" @click="openOperation('cancel',row.ID)">取消</button><button class="btn btn-primary btn-small" @click="openOperation('reconcile',row.ID)">异常结算</button></div></td></tr></tbody></table></div><div class="mobile-list"><article v-for="row in items" :key="String(row.ID)" class="summary-card"><div class="row-between"><strong>{{row.Name||'未命名远征'}}</strong><span class="badge">{{statusLabel(row.Status)}}</span></div><span>玩家 · …{{String(row.AccountID||'').slice(-8)||'-'}}</span><span>结束 · {{dateText(row.EndsAt)}}</span><span>奖励 · {{row.RewardItem||'无'}} × {{row.RewardQuantity||0}}</span><div v-if="row.Status==='running'" class="actions"><button class="btn btn-ghost btn-small" @click="openOperation('cancel',row.ID)">取消</button><button class="btn btn-primary btn-small" @click="openOperation('reconcile',row.ID)">结算</button></div></article></div></div>
    <UiPagination v-if="!loading" :page="page" :limit="limit" :total="total" @change="changePage" @update:limit="changeLimit"/>
  </template>

  <template v-else-if="tab==='growth'&&growth">
    <div v-if="growth.warnings.length" class="notice warning"><IconAlertTriangle :size="18"/><div><strong>正在使用默认规则兜底</strong><span>{{growth.warnings.join('；')}}</span></div></div>
    <div class="metric-strip five"><article><span>宠物数量</span><strong>{{growth.summary.player_count}}</strong></article><article><span>定位覆盖率</span><strong>{{percent(growth.summary.role_coverage_rate)}}</strong></article><article><span>性格形成率</span><strong>{{percent(growth.summary.personality_formation_rate)}}</strong></article><article><span>未形成性格</span><strong>{{growth.summary.personality_unformed}}</strong></article><article><span>已配置规则</span><strong>{{growth.summary.configured_rule_count}}</strong></article></div>
    <div v-if="growth.summary.player_count===0" class="notice"><IconTimeline :size="18"/><div><strong>暂无玩家行为数据，成长规则已经可以配置</strong><span>玩家产生照料、远征与支援行为后，这里的覆盖率和分布会自动更新。</span></div></div>
    <div class="section-heading"><div><span class="kicker">运营数据</span><h2>成长生态分布</h2></div><span>只展示数据库真实数据</span></div>
    <div class="analytics-grid"><article v-for="section in [{title:'宠物定位',rows:growth.roles},{title:'姿态使用',rows:growth.stances},{title:'性格形成',rows:growth.personalities},{title:'技能组覆盖',rows:growth.skills}]" :key="section.title" class="analytics-card"><h3>{{section.title}}</h3><div v-for="row in section.rows" :key="row.name" class="bar-row"><div><span>{{row.name}}</span><strong>{{row.count}} 人 · {{percent(row.percentage)}}</strong></div><div class="bar"><i :style="{width:`${Math.min(row.percentage,100)}%`}"/></div><small>{{row.description||'暂无说明'}}</small></div></article></div>
    <div class="section-heading rules-title"><div><span class="kicker">成长规则</span><h2>实际玩法配置</h2></div><span :class="['save-state',{dirty}]">{{dirty?'有未保存修改':'规则与当前配置一致'}}</span></div>
    <div class="rule-workspace"><aside class="rule-nav"><button v-for="item in ([['roles','宠物定位',rules.roles.length],['stances','远征姿态',rules.stances.length],['personalities','性格规则',rules.personalities.length],['codex','图鉴目录',rules.codex.length]] as [RuleDomain,string,number][] )" :key="item[0]" :class="{active:ruleDomain===item[0]}" @click="ruleDomain=item[0]"><span>{{item[1]}}</span><b>{{item[2]}}</b></button></aside><div class="rule-list"><header><div><strong>{{({roles:'宠物定位',stances:'远征姿态',personalities:'性格形成规则',codex:'图鉴目录'} as Record<RuleDomain,string>)[ruleDomain]}}</strong><small>排序值越小越靠前；停用后聊天命令不可选。</small></div><button class="btn btn-primary btn-small" @click="addRule(ruleDomain)">新增规则</button></header><button v-for="(row,index) in rules[ruleDomain]" :key="String((row as any).name||(row as any).entry_key)+index" class="rule-item" @click="openRule(ruleDomain,index)"><span class="rule-icon"><IconBook2 :size="18"/></span><span><strong>{{(row as any).name||(row as any).entry_key||'未命名规则'}}</strong><small>{{(row as any).description||`${(row as any).category||''} ${(row as any).region||''}`||'暂无说明'}}</small></span><span class="badge" :class="(row as any).enabled?'badge-success':''">{{(row as any).enabled?'启用':'停用'}}</span><IconArrowRight :size="17"/></button></div></div>
  </template>

  <template v-else-if="tab==='codex'&&codex"><div class="notice-banner"><strong>图鉴目录与探索记录</strong><span>玩家完成配置了图鉴条目的探索目标时，会自动推进对应发现记录。活动进度与图鉴进度分别结算。</span></div><div class="metric-strip"><article><span>目录条目</span><strong>{{codex.summary.catalog_count}}</strong></article><article><span>已有发现</span><strong>{{codex.summary.discovered_entries}}</strong></article><article><span>目录发现率</span><strong>{{percent(codex.summary.discovery_rate)}}</strong></article><article><span>玩家进度</span><strong>只读</strong></article></div><UiState v-if="codex.items.length===0" title="没有符合条件的图鉴条目" description="请在成长运营的图鉴目录中新增或启用条目。" action-label="前往配置" @action="setTab('growth');ruleDomain='codex'"/><div v-else class="data-panel"><div class="data-panel-head"><strong>图鉴目录与玩家进度</strong><span>没有玩家时仍展示完整目录</span></div><div class="desktop-table"><table><thead><tr><th>图鉴条目</th><th>类别</th><th>区域</th><th>发现人数</th><th>完成人数</th><th>平均进度</th><th>状态</th></tr></thead><tbody><tr v-for="row in codex.items" :key="`${row.category}:${row.entry_key}`"><td><strong>{{row.entry_key}}</strong><small>{{row.description||'暂无说明'}}</small></td><td>{{row.category}}</td><td>{{row.region}}</td><td>{{row.discovered_players}}</td><td>{{row.completed_players}}</td><td>{{percent(row.average_progress)}}</td><td><span class="badge" :class="row.enabled?'badge-success':''">{{row.enabled?'启用':'停用'}}</span></td></tr></tbody></table></div><div class="mobile-list"><article v-for="row in codex.items" :key="row.entry_key" class="summary-card"><div class="row-between"><strong>{{row.entry_key}}</strong><span class="badge">{{row.enabled?'启用':'停用'}}</span></div><span>{{row.category}} · {{row.region}}</span><span>发现 {{row.discovered_players}} 人 · 完成 {{row.completed_players}} 人</span><span>平均进度 {{percent(row.average_progress)}}</span></article></div></div></template>

  <template v-else-if="tab==='rewards'"><div class="metric-strip"><article><span>已配置活动</span><strong>{{events.length}}</strong></article><article><span>里程碑数量</span><strong>{{rewards.length}}</strong></article><article><span>奖励总量</span><strong>{{rewards.reduce((sum,row)=>sum+Number(row.quantity||0),0)}}</strong></article><article :class="{warning:rewardWarnings.length}"><span>配置警告</span><strong>{{rewardWarnings.length}}</strong></article></div><div v-if="rewardWarnings.length" class="notice warning"><IconAlertTriangle :size="18"/><div><strong>奖励配置需要处理</strong><span>{{rewardWarnings.join('；')}}</span></div></div><div class="section-heading"><div><span class="kicker">只读运营视图</span><h2>活动里程碑时间线</h2></div><RouterLink class="btn btn-primary" :to="{name:'content',query:{tab:'rewards'}}"><IconSettings :size="17"/>前往内容配置</RouterLink></div><UiState v-if="groupedRewards.length===0" title="尚未配置奖励轨道" description="先在内容配置创建活动，再为活动添加明确的里程碑奖励。"/><div v-else class="timeline-list"><article v-for="group in groupedRewards" :key="group.event.key"><header><div><strong>{{group.event.name}}</strong><small>{{group.event.key}} · {{group.event.region}}</small></div><span class="badge" :class="group.event.active?'badge-success':''">{{group.event.active?'启用':'停用'}}</span></header><div v-if="group.rewards.length" class="timeline"><div v-for="reward in group.rewards" :key="reward.milestone"><i/><span><b>{{reward.milestone}}</b><small>里程碑</small></span><span><strong>{{reward.reward_name||reward.reward_key}} × {{reward.quantity}}</strong><small>{{reward.reward_type==='currency'?'货币':'物品'}} · {{reward.description||'无额外说明'}}</small></span></div></div><p v-else>这个活动还没有奖励里程碑。</p></article></div></template>

  <UiDrawer :open="ruleIndex>=0" :title="selectedRule?.name||selectedRule?.entry_key||'新增成长规则'" description="这里的配置会直接驱动聊天命令和成长判断。" @close="ruleIndex=-1"><form v-if="selectedRule" class="drawer-form" @submit.prevent="ruleIndex=-1"><div class="form-section"><h3>基本信息</h3><label v-if="ruleDomain!=='codex'">名称<input v-model="selectedRule.name"/></label><template v-else><div class="form-row"><label>类别<input v-model="selectedRule.category" placeholder="生物 / 遗迹 / 生态"/></label><label>区域<input v-model="selectedRule.region" placeholder="森林"/></label></div><label>条目名称<input v-model="selectedRule.entry_key"/></label><div class="form-row"><label>来源类型<select v-model="selectedRule.source_type"><option value="zone">地图区域</option><option value="monster">怪物</option><option value="landmark">地标</option><option value="boss">地图首领</option><option value="manual">手动推进</option></select></label><label>来源键<input v-model="selectedRule.source_key" placeholder="例如 forest-edge"/></label></div><small class="field-help">来源键填写冒险世界配置中的区域、怪物、地标或首领 key；选择手动推进时可留空。</small></template><label>运营说明<textarea v-model="selectedRule.description" rows="3"/></label></div><div v-if="ruleDomain==='roles'" class="form-section"><h3>固定技能组</h3><div class="form-row"><label>技能一<input v-model="selectedRule.skill_1"/></label><label>技能二<input v-model="selectedRule.skill_2"/></label></div><label>技能三<input v-model="selectedRule.skill_3"/></label></div><div v-if="ruleDomain==='personalities'" class="form-section"><h3>形成条件</h3><div class="form-row"><label>行为维度<select v-model="selectedRule.dimension"><option value="care">照料</option><option value="explore">探索</option><option value="support">支援</option></select></label><label>最低阈值<input v-model.number="selectedRule.min_threshold" type="number" min="1"/></label></div></div><div class="form-section"><h3>发布设置</h3><div class="form-row"><label>排序<input v-model.number="selectedRule.sort_order" type="number"/></label><label class="check-line"><input v-model="selectedRule.enabled" type="checkbox"/>在游戏中启用</label></div></div></form><template #footer><div class="drawer-actions"><button class="btn btn-danger btn-small" @click="removeRule">删除规则</button><button class="btn btn-primary" @click="ruleIndex=-1">完成编辑</button></div></template></UiDrawer>
  <UiModal :open="!!operation.type" :title="operation.type==='cancel'?'取消异常远征':'重新结算远征'" description="操作会校验当前状态并写入审计日志。" :busy="busy" @close="operation.type=''"><form class="operation-box" @submit.prevent="execute"><label>操作原因<textarea v-model="operation.reason" rows="4"/></label><div class="actions"><button type="button" class="btn btn-ghost" @click="operation.type=''">返回</button><button class="btn btn-danger" :disabled="busy">确认执行</button></div></form></UiModal>
  <UiModal :open="confirmation.open" :title="confirmation.title" :description="confirmation.description" size="small" @close="confirmation.open=false"><template #footer><button class="btn btn-ghost" @click="confirmation.open=false">取消</button><button class="btn btn-danger" @click="confirmRequestedAction">确认继续</button></template></UiModal>
</section></template>

