@media(max-width:700px){.metric-strip,.metric-strip.five{grid-template-columns:1fr 1fr}.metric-strip article:nth-child(2n){border-right:0}.rule-workspace{grid-template-columns:1fr}.rule-nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid var(--border-color)}.rule-nav button{min-width:125px}.section-heading{align-items:flex-start;flex-direction:column}.form-row{grid-template-columns:1fr}.timeline{padding-bottom:6px}}
